document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".add-to-cart-form").forEach(e=>{e.addEventListener("submit",async t=>{t.preventDefault();const a=new FormData(e);try{const t=await fetch(e.action,{method:"POST",body:a,headers:{"X-Requested-With":"XMLHttpRequest"}});(await t.json()).success&&alert("Added to cart successfully!")}catch(e){console.error("Cart error:",e)}})})});